  // as lit by something rather than pasted on. Kept under 3% so it never becomes
  // a gradient wash.
  let sun = uniforms.sunDir * vec2f(0.5, -0.5) + vec2f(0.5);
  let d = length((uv - sun) * vec2f(aspect, 1.0));
